/* Wspólne szablony. build.mjs zapisuje ich wynik jako osobne, edytowalne strony HTML. */
window.UI = (() => {
 const S = window.STORE;
 const esc = value => String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money = n => n.toLocaleString('pl-PL',{style:'currency',currency:'PLN'});
 const icons={search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/>',bag:'<path d="M5 7h14l2 14H3L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',heart:'<path d="M20.5 5.5c-3-3-6-1-8.5 1.5C9.5 4.5 6.5 2.5 3.5 5.5S3 12 12 20c9-8 11.5-11.5 8.5-14.5Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 5 5L20 7"/>',paw:'<ellipse cx="12" cy="16" rx="6" ry="4.5"/><ellipse cx="4.8" cy="9" rx="2.4" ry="3"/><ellipse cx="10" cy="5.5" rx="2.3" ry="3"/><ellipse cx="16" cy="6" rx="2.3" ry="3"/><ellipse cx="20" cy="11" rx="2.3" ry="3"/>',leaf:'<path d="M20 3C9 2 2 6 4 14s14 10 16-11Z"/><path d="M4 21 15 9"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7.5 5 17 9"/>',chat:'<path d="M21 11a9 9 0 0 1-13 8L3 21l1-6a9 9 0 1 1 17-4Z"/><path d="M8 10h8M8 14h5"/>',play:'<path d="m9 5 11 7-11 7V5Z"/>'};
 const icon = (name, cls='') => `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.paw}</svg>`;
 const arrow=icon('arrow');
 const logo=()=>`<a class="logo" href="index.html" aria-label="Burek — strona główna">${icon('paw')}<span>burek<span class="logo-dot">.</span></span></a>`;
 function header(page){return `<a class="skip-link" href="#main">Przejdź do treści</a><div class="topbar"><div class="container"><span>Małe rzeczy. Wielka radość. ${icon('heart')}</span><div><a href="o-nas.html">Poznaj Burka</a><span>·</span><a href="kontakt.html">Porozmawiajmy</a></div></div></div><header class="header"><div class="container header-main">${logo()}<form class="search" id="search-form" role="search"><label class="sr-only" for="search-input">Szukaj w sklepie</label>${icon('search')}<input id="search-input" name="q" type="search" placeholder="Czego potrzebuje Twój pupil?" autocomplete="off"><button aria-label="Szukaj produktów" type="submit">${arrow}</button></form><div class="header-actions"><button class="icon-button" data-action="favorites" aria-label="Pokaż ulubione">${icon('heart')}<span class="desktop-only">Ulubione</span><span class="favorite-count badge-count" hidden>0</span></button><button class="icon-button cart-button" data-action="cart" aria-label="Otwórz koszyk">${icon('bag')}<span class="desktop-only">Koszyk</span><span class="cart-count badge-count">0</span></button><button class="icon-button mobile-menu" data-action="menu" aria-label="Otwórz menu" aria-expanded="false" aria-controls="main-nav">${icon('menu')}</button></div></div><nav class="nav" id="main-nav" aria-label="Nawigacja główna"><div class="container nav-inner">${S.categories.map(c=>`<a href="${c.id}.html" ${page===c.id?'aria-current="page"':''}>${c.name}</a>`).join('')}<span class="nav-separator"></span><a class="sale-link" href="promocje.html" ${page==='promocje'?'aria-current="page"':''}>Małe okazje <span>♥</span></a><a href="poradnik.html" ${page==='poradnik'?'aria-current="page"':''}>Poradnik</a><a href="o-nas.html" ${page==='o-nas'?'aria-current="page"':''}>O nas</a></div></nav></header>`;}
 function footer(){return `<footer class="footer"><div class="container footer-main"><div class="footer-brand">${logo()}<p>Bo każdy pupil zasługuje<br>na swój kawałek szczęścia.</p><span class="footer-heart">Z miłości do zwierząt ${icon('heart')}</span></div><div><h3>Dla Twojego pupila</h3>${S.categories.map(c=>`<a href="${c.id}.html">${c.name}</a>`).join('')}</div><div><h3>Dobry adres</h3><a href="o-nas.html">O Burku</a><a href="poradnik.html">Poradnik opiekuna</a><a href="promocje.html">Małe okazje</a><a href="kontakt.html">Kontakt i pomoc</a></div><div class="footer-note"><h3>Masz chwilę?</h3><p>Zajrzyj do poradnika.<br>Znajdziesz tam pomysły<br>na Waszą codzienność.</p><a class="text-link" href="poradnik.html">Poczytaj z Burkiem ${arrow}</a></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Burek. Dobrze być razem.</span><span>Projekt demonstracyjny · przykładowy asortyment i ceny</span></div></footer><dialog id="shop-dialog" aria-labelledby="dialog-title"><div id="dialog-content"></div></dialog><div class="toast" id="toast" role="status" aria-live="polite"></div><button class="back-top icon-button" data-action="top" aria-label="Wróć na górę">↑</button>`;}
 function breadcrumbs(label){return `<div class="container breadcrumbs"><a href="index.html">Strona główna</a><span>/</span><span>${label}</span></div>`;}
 function sectionTitle(kicker,title,link,href){return `<div class="section-heading reveal"><div><p class="eyebrow">${kicker}</p><h2>${title}</h2></div>${link?`<a class="text-link" href="${href}">${link} ${arrow}</a>`:''}</div>`;}
 function product(p){return `<article class="product-card reveal" data-product="${p.id}"><div class="product-visual"><button class="product-open" data-action="product" data-id="${p.id}" aria-label="Zobacz ${esc(p.name)}">${window.art(p.art,p.color)}</button>${p.badge?`<span class="product-badge ${p.old?'orange':''}">${p.badge}</span>`:''}<button class="favorite-toggle icon-button" data-action="favorite" data-id="${p.id}" aria-label="Dodaj ${esc(p.name)} do ulubionych" aria-pressed="false">${icon('heart')}</button></div><div class="product-info"><p class="product-brand">${p.brand}</p><h3><button data-action="product" data-id="${p.id}">${p.name}</button></h3><p class="product-size">${p.size}</p><div class="product-bottom"><div>${p.old?`<del>${money(p.old)}</del>`:''}<strong>${money(p.price)}</strong></div><button class="add-button" data-action="add" data-id="${p.id}" aria-label="Dodaj ${esc(p.name)} do koszyka">${icon('plus')}</button></div></div></article>`;}
 const productGrid=products=>`<div class="product-grid">${products.map(product).join('')}</div>`;
 function categories(){return `<section class="container section categories-section">${sectionTitle('KAŻDY MA SWÓJ ŚWIAT','Dla kogo dziś coś dobrego?')}<div class="categories-grid">${S.categories.map(c=>`<a class="category-card reveal" href="${c.id}.html"><div class="category-visual" style="--tile:${c.color}">${window.art(c.animal)}</div><span>${c.name} ${arrow}</span></a>`).join('')}</div></section>`;}
 function article(a){return `<article class="article-card reveal"><button class="article-image" data-action="article" data-id="${a.id}" aria-label="Czytaj: ${esc(a.title)}" style="background:${a.color}">${window.art(a.animal)}<span class="article-number">0${S.articles.indexOf(a)+1}</span></button><p class="eyebrow">${a.tag} <span>· 3 min czytania</span></p><h3><button data-action="article" data-id="${a.id}">${a.title}</button></h3><p>${a.text}</p><button class="text-link" data-action="article" data-id="${a.id}">Przeczytaj ${arrow}</button></article>`;}
 function journal(full=false){return `<section class="container section">${sectionTitle('DOBRZE WIEDZIEĆ',full?'Poradnik dobrego opiekuna.':'Trochę wiedzy. Dużo troski.',full?'':'Cały poradnik','poradnik.html')}<div class="article-grid">${S.articles.map(article).join('')}</div></section>`;}
 function home(){return `<section class="hero"><div class="container hero-inner"><div class="hero-copy reveal"><p class="eyebrow"><span class="live-dot"></span> DLA TYCH, KTÓRZY SĄ RODZINĄ</p><h1>Małe łapki.<br>Wielka <em>miłość.</em></h1><p class="hero-description">Pełna miska, ulubiona zabawka i radość z bycia razem.<br>W Burku znajdziesz małe rzeczy, które znaczą wiele.</p><div class="hero-buttons"><a class="button primary" href="dla-psa.html">Odkryj psi świat ${arrow}</a><a class="button ghost" href="dla-kota.html">A może coś dla kota? ${arrow}</a></div><div class="hero-note">${icon('paw')} Dla małych przyjaciół i wielkich przyjaźni.</div></div><div class="hero-art reveal"><div class="hero-blob"></div><span class="hero-spark spark-one">✳</span><span class="hero-spark spark-two">✦</span><div class="hero-dog">${window.art('dog')}</div><div class="hero-cat">${window.art('cat')}</div><div class="floating-label">${icon('heart')} Ich szczęście?<br><strong>Nasza ulubiona sprawa.</strong></div><span class="handwritten">dobrze być razem ♡</span></div></div></section><div class="values-strip"><div class="container"><div>${icon('leaf')}<span>Uważne wybory<br><small>dla codziennych potrzeb</small></span></div><div>${icon('paw')}<span>Od miski po zabawkę<br><small>poznaj świat swojego pupila</small></span></div><div>${icon('chat')}<span>Wiedza pod łapą<br><small>poradnik dobrego opiekuna</small></span></div></div></div>${categories()}<section class="container section bestseller-section">${sectionTitle('MAŁE POWODY DO RADOŚCI','Pupil już wie, co lubi.','Zobacz wszystkie okazje','promocje.html')}<div class="product-tabs" role="group" aria-label="Wybierz produkty"><button class="active" data-home-filter="all" aria-pressed="true">Wszystkie</button><button data-home-filter="dla-psa" aria-pressed="false">Dla psa</button><button data-home-filter="dla-kota" aria-pressed="false">Dla kota</button></div><div id="home-products">${productGrid(S.products.slice(0,4))}</div><p class="catalog-note">Przykładowy katalog Burka. Ceny i produkty służą prezentacji strony.</p></section><section class="container story-banner reveal"><div class="story-text"><p class="eyebrow">WSPÓLNE CHWILE SĄ NAJLEPSZE</p><h2>Cały świat<br>w jednym <em>merdnięciu.</em></h2><p>Nie potrzeba wielkich okazji. Czasem wystarczy spacer, nowa zabawka i ktoś, kto zawsze cieszy się na Twój widok.</p><a class="button dark" href="o-nas.html">Poznaj Burka ${arrow}</a></div><div class="story-illustration">${window.art('dog')}<span>♡</span></div></section>${journal()}<section class="container instagram-section section">${sectionTitle('CHWILE Z PSIEGO ŚWIATA','Mała łapka, duża ciekawość.')}<div class="video-feature reveal"><div class="video-wrap"><video controls playsinline preload="metadata" aria-label="Pudel Kosa sprawdza paczkę — materiał z profilu unizoo.pl"><source src="assets/media/instagram-video-02.mp4" type="video/mp4">Twoja przeglądarka nie odtwarza wideo.</video></div><div class="video-copy"><span class="eyebrow">ZNALEZIONE NA INSTAGRAMIE</span><h3>Każda paczka musi przejść<br>psią kontrolę jakości.</h3><p>Zobacz, jak pudel Kosa zagląda do przesyłki. Chwila z życia małego, bardzo ciekawskiego inspektora.</p><a class="text-link" href="https://www.instagram.com/unizoo.pl/" target="_blank" rel="noopener noreferrer">Źródło: profil @unizoo.pl ${arrow}</a><p class="source-note">Materiał zewnętrzny · nie przedstawia oferty ani współpracy sklepu Burek.</p></div></div></section>`;}
 function categoryPage(id){const c=S.categories.find(x=>x.id===id);return `${breadcrumbs(c.name)}<section class="container category-hero" style="--tile:${c.color}"><div><p class="eyebrow">BUREK / ${c.name.toUpperCase()}</p><h1>${c.title}</h1><p>${c.description}</p></div><div>${window.art(c.animal)}</div></section><section class="container section catalog" data-category="${id}"><div class="catalog-toolbar"><div class="product-tabs" role="group" aria-label="Rodzaj produktu"><button class="active" data-type="all" aria-pressed="true">Wszystko</button><button data-type="Karmy" aria-pressed="false">Karmy</button><button data-type="Zabawki" aria-pressed="false">Zabawki</button><button data-type="Akcesoria" aria-pressed="false">Akcesoria</button></div><label class="sort-label">Sortuj <select id="sort-products"><option value="default">Polecane</option><option value="price-up">Cena: rosnąco</option><option value="price-down">Cena: malejąco</option><option value="name">Nazwa: A–Z</option></select></label></div><p class="result-count" id="result-count"></p><div id="catalog-products">${productGrid(S.products.filter(p=>p.category===id))}</div><p class="catalog-note">Katalog demonstracyjny · przykładowe produkty, ilustracje i ceny.</p></section><section class="container care-note reveal">${icon('heart')}<div><h2>Każdy pupil jest inny.</h2><p>Dobierz karmę i akcesoria do gatunku, wieku i potrzeb swojego zwierzaka. Poznaj go jeszcze lepiej z naszym poradnikiem.</p></div><a class="text-link" href="poradnik.html">Zajrzyj do poradnika ${arrow}</a></section>`;}
 function offers(){return `${breadcrumbs('Małe okazje')}<section class="container page-intro"><p class="eyebrow">DOBRE RZECZY W DOBRYCH CENACH</p><h1>Małe okazje.<br>Wielkie <em>merdanie.</em></h1><p>Coś do miski, coś do zabawy. Odkryj przykładowe okazje z katalogu Burka.</p></section><section class="container section offers-grid">${productGrid(S.products.filter(p=>p.old))}<p class="catalog-note">Promocje i przekreślone ceny są przykładowymi danymi demonstracyjnymi.</p></section><section class="container care-note reveal">${icon('box')}<div><h2>Dobry wybór zaczyna się od potrzeb.</h2><p>Porównaj wielkość, przeznaczenie i rodzaj produktu. Wybierz coś, co naprawdę ucieszy Twojego pupila.</p></div><a class="text-link" href="dla-psa.html">Odkryj katalog ${arrow}</a></section>`;}
 function guide(){return `${breadcrumbs('Poradnik')}<section class="container page-intro"><p class="eyebrow">NA DOBRY POCZĄTEK I KAŻDY KOLEJNY DZIEŃ</p><h1>Lepiej rozumieć.<br>Jeszcze bardziej <em>kochać.</em></h1><p>Codzienność z pupilem to małe odkrycia. Zebraliśmy kilka pomysłów, które warto mieć pod łapą.</p></section>${journal(true)}<section class="container section"><div class="inspiration reveal"><img src="assets/media/instagram-05.jpg" width="1080" height="1339" loading="lazy" alt="Ilustracja z Instagrama unizoo.pl: sześć rzeczy, które denerwują kota"><div><p class="eyebrow">INSPIRACJA Z INSTAGRAMA</p><h2>Koty mają<br>swoje zdanie.</h2><p>Chcesz lepiej poznać ich zwyczaje? Zobacz materiał edukacyjny opublikowany na profilu @unizoo.pl.</p><a class="text-link" href="https://www.instagram.com/unizoo.pl/p/Dd9KHQoDtx2/" target="_blank" rel="noopener noreferrer">Przejdź do oryginalnego wpisu ${arrow}</a><p class="source-note">Autor materiału: @unizoo.pl. Grafika zewnętrzna, niezwiązana z ofertą sklepu Burek.</p></div></div></section>`;}
 function about(){return `${breadcrumbs('O nas')}<section class="container about-hero"><div><p class="eyebrow">CZEŚĆ, TU BUREK!</p><h1>Dobrze, że<br>jesteście <em>razem.</em></h1><p>Burek to pomysł na sklep dla tych, którzy widzą w zwierzętach rodzinę. Dla miłośników mokrych nosów, porannego mruczenia i małych, codziennych rytuałów.</p><a class="button primary" href="dla-psa.html">Znajdź coś dla przyjaciela ${arrow}</a></div><div class="about-art">${window.art('dog')}${window.art('cat')}</div></section><section class="container section"><div class="about-statement reveal"><span>01 / NASZA FILOZOFIA</span><h2>Nie trzeba mówić tym samym językiem,<br>żeby rozumieć się <em>najlepiej.</em></h2><p>Spacer tą samą ścieżką. Ulubione miejsce na kanapie. Miska postawiona dokładnie tam, gdzie trzeba. Wierzymy, że to właśnie z takich chwil składa się dobre życie z pupilem.</p></div><div class="principles"><article class="reveal">${icon('heart')}<h3>Troska na co dzień</h3><p>Zaczynamy od potrzeb zwierzęcia. Od odpowiedniej karmy po bezpieczne, wygodne otoczenie.</p></article><article class="reveal">${icon('leaf')}<h3>Świadome wybory</h3><p>Czytelne opisy i prosty katalog pomagają spokojnie porównać to, czego szukasz.</p></article><article class="reveal">${icon('paw')}<h3>Radość z bycia razem</h3><p>Bo najlepszym dodatkiem do każdej zabawki jest czas spędzony z ukochanym opiekunem.</p></article></div></section><section class="container story-banner reveal"><div class="story-text"><p class="eyebrow">POZNAJ NASZ ŚWIAT</p><h2>Mały sklep.<br>Dużo <em>serca.</em></h2><p>Burek jest autorskim projektem demonstracyjnym sklepu zoologicznego. Katalog i ceny są przykładowe. Materiały z Instagrama mają osobno wskazane źródło.</p><a class="button dark" href="kontakt.html">Porozmawiajmy ${arrow}</a></div><div class="story-illustration">${window.art('rabbit')}</div></section>`;}
 function contact(){return `${breadcrumbs('Kontakt')}<section class="container page-intro"><p class="eyebrow">JESTEŚMY PO TEJ SAMEJ STRONIE MISKI</p><h1>Porozmawiajmy<br>o Twoim <em>pupilu.</em></h1><p>Nie wiesz, od czego zacząć? Zobacz odpowiedzi na częste pytania albo przygotuj wiadomość.</p></section><section class="container contact-layout section"><div><h2>Wiadomość do Burka</h2><p class="muted">To formularz demonstracyjny. Przygotuje tekst do skopiowania; nie wysyła wiadomości.</p><form id="contact-form" class="contact-form"><label>Jak masz na imię?<input required name="name" autocomplete="given-name" placeholder="Twoje imię" maxlength="100"></label><label>Twój adres e-mail<input required name="email" type="email" autocomplete="email" placeholder="np. imie@example.com" maxlength="200"></label><label>W czym możemy pomóc?<select name="subject"><option>Wybór produktu</option><option>Pytanie o sklep</option><option>Inny temat</option></select></label><label>Twoja wiadomość<textarea required name="message" rows="5" minlength="10" maxlength="4000" placeholder="Napisz kilka słów…"></textarea></label><button class="button primary" type="submit">Przygotuj wiadomość ${arrow}</button><p id="contact-result" class="form-result" role="status"></p></form></div><div class="faq"><p class="eyebrow">DOBRZE WIEDZIEĆ</p><h2>Najczęstsze pytania</h2><details open><summary>Czy mogę tutaj złożyć zamówienie?</summary><p>To projekt demonstracyjny. Możesz przeglądać katalog, dodawać produkty do koszyka i pobrać listę zakupów. Strona nie pobiera płatności ani nie składa zamówień.</p></details><details><summary>Jak dobrać produkt dla pupila?</summary><p>Skorzystaj z kategorii zwierząt i filtrów. Wybierając prawdziwy produkt, sprawdź jego przeznaczenie i zalecenia producenta. W kwestiach zdrowotnych skontaktuj się z lekarzem weterynarii.</p></details><details><summary>Gdzie zapisuje się koszyk?</summary><p>Koszyk i ulubione zapisują się lokalnie w Twojej przeglądarce. Nie są przesyłane na serwer. Możesz je edytować lub wyczyścić w dowolnym momencie.</p></details><details><summary>Skąd pochodzą materiały z Instagrama?</summary><p>Z publicznych materiałów widocznych na profilu @unizoo.pl. Każdy wykorzystany materiał ma podpis i odnośnik do źródła. Burek jest osobnym projektem.</p></details><div class="contact-dog">${window.art('dog')}<span>dobrze, że pytasz ♡</span></div></div></section>`;}
 const pages={'index':home,'promocje':offers,'poradnik':guide,'o-nas':about,'kontakt':contact};
 const titles={'index':'Burek — małe łapki, wielka miłość','promocje':'Małe okazje — Burek','poradnik':'Poradnik opiekuna — Burek','o-nas':'Poznaj Burka — sklep zoologiczny','kontakt':'Kontakt i pomoc — Burek'};
 function page(id){return S.categories.some(c=>c.id===id)?categoryPage(id):(pages[id]||home)();}
 return {esc,money,icon,logo,header,footer,product,productGrid,article,page,titles};
})();
